import { useContext } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import './videos.scss';

const Videos = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);

  if (!currentUser) {
    return null;
  }

  // Mock videos data (replace with API)
  const videos = [
    { id: 1, url: 'https://www.w3schools.com/html/mov_bbb.mp4', title: 'Sample Video 1' },
    { id: 2, url: 'https://www.w3schools.com/html/mov_bbb.mp4', title: 'Sample Video 2' },
  ];

  return (
    <div className={`videos ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{currentUser.name}'s Videos</h2>
      <div className="video-grid">
        {videos.map(video => (
          <div key={video.id} className="video-card">
            <video controls src={video.url} />
            <p>{video.title}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Videos;
